'use strict'

import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { overlaps } from '../../utils/box'
import { TILE_WIDTH, TILE_HEIGHT, SOUND_SHIELD } from '../../constant'
import { DIRECTION_VECTORS, inset, isInside, drawImage, directionOf } from './common'

// What stops a projectile: any shield facing it, only the magical one, or nothing
export const BLOCK_SHIELD = 'shield'
export const BLOCK_MAGICAL_SHIELD = 'magical'

const ROCK_SPEED = 6
const ARROW_SPEED = 8
const SWORD_SPEED = 6
const FIREBALL_SPEED = 3
const FIREBALL_FRAME_STEPS = 2
// A fireball stays 17 frames where it was spat before flying off (measured on the zoras)
const FIREBALL_WAIT_STEPS = 17
// In hearts
const ROCK_DAMAGE = 0.5
const ARROW_DAMAGE = 0.5
const FIREBALL_DAMAGE = 0.5
const SMALL_INSET = 10
const BALL_INSET = 11

// Flies straight on (vx, vy) per step, over the obstacles, up to the edge of the screen
class Projectile {
  constructor (x, y, vx, vy, { damage, block, insetValue = SMALL_INSET }) {
    this.x = x
    this.y = y
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.vx = vx
    this.vy = vy
    this.direction = directionOf(vx, vy)
    this.damage = damage
    this.block = block
    this.insetValue = insetValue
    this.steps = 0
    this.done = false
  }

  getBox () {
    return inset(this.x, this.y, this.width, this.height, this.insetValue)
  }

  isBlockedBy (link) {
    if (!this.block || !link.canBlock(this.direction)) {
      return false
    }
    return this.block === BLOCK_SHIELD || link.hasMagicalShield
  }

  process (map, link) {
    this.steps++
    this.x += this.vx
    this.y += this.vy
    if (!isInside(map, this.x, this.y, this.width, this.height)) {
      this.done = true
      return
    }
    if (!overlaps(this.getBox(), link.getBodyBox())) {
      return
    }
    this.done = true
    if (this.isBlockedBy(link)) {
      soundManager.play(resource.getSound(SOUND_SHIELD))
      return
    }
    link.hurt(this.damage, this.getBox())
  }

  spriteName () {}

  frame () {
    return 0
  }

  draw (context) {
    drawImage(context, resource.getSprite(this.spriteName()), this.frame(), this.x, this.y, this.width, this.height)
  }
}

// Thrown by the octoroks, stopped by any shield
class Rock extends Projectile {
  constructor (x, y, direction) {
    const [dx, dy] = DIRECTION_VECTORS[direction]
    super(x, y, dx * ROCK_SPEED, dy * ROCK_SPEED, { damage: ROCK_DAMAGE, block: BLOCK_SHIELD })
  }

  spriteName () {
    return 'octorok_rock'
  }
}

// Shot by the moblins, stopped by any shield
class Arrow extends Projectile {
  constructor (x, y, direction) {
    const [dx, dy] = DIRECTION_VECTORS[direction]
    super(x, y, dx * ARROW_SPEED, dy * ARROW_SPEED, { damage: ARROW_DAMAGE, block: BLOCK_SHIELD })
  }

  spriteName () {
    return `arrow_${this.direction}`
  }
}

// Thrown by the lynels (color: red or blue), stopped by the magical shield only
class Sword extends Projectile {
  constructor (x, y, direction, color, damage) {
    const [dx, dy] = DIRECTION_VECTORS[direction]
    super(x, y, dx * SWORD_SPEED, dy * SWORD_SPEED, { damage, block: BLOCK_MAGICAL_SHIELD })
    this.color = color
  }

  spriteName () {
    return `sword_${this.color}_${this.direction}`
  }
}

// Spat by the zoras straight at Link, stopped by the magical shield only; it blinks
class Fireball extends Projectile {
  constructor (x, y, target) {
    const dx = target.x - x
    const dy = target.y - y
    const length = Math.hypot(dx, dy) || 1
    super(x, y, dx / length * FIREBALL_SPEED, dy / length * FIREBALL_SPEED, { damage: FIREBALL_DAMAGE, block: BLOCK_MAGICAL_SHIELD, insetValue: BALL_INSET })
    this.wait = FIREBALL_WAIT_STEPS
  }

  process (map, link) {
    if (this.wait > 0) {
      this.wait--
      this.steps++
      return
    }
    super.process(map, link)
  }

  spriteName () {
    return 'fireball'
  }

  frame () {
    return Math.floor(this.steps / FIREBALL_FRAME_STEPS) % 4
  }
}

// The boomerang of a goriya (object $5C), measured on the red ones of level 1: 2.5 NES pixels a frame (3, then 2)
// for 34 frames, 1 pixel a frame for 16, back 1 pixel a frame for 16, then 2 pixels a frame straight to the goriya,
// which waits for it. It takes a heart from Link and comes back; a shield stops it (not measured)
const ENEMY_BOOMERANG_FAST = [6, 4]
const ENEMY_BOOMERANG_FAST_STEPS = 34
const ENEMY_BOOMERANG_SLOW = 2
const ENEMY_BOOMERANG_SLOW_STEPS = 16
const ENEMY_BOOMERANG_BACK = 4
const ENEMY_BOOMERANG_DAMAGE = 1
const ENEMY_BOOMERANG_FRAME_STEPS = 2

class EnemyBoomerang extends Projectile {
  constructor (thrower, direction) {
    super(thrower.x, thrower.y, 0, 0, { damage: ENEMY_BOOMERANG_DAMAGE, block: BLOCK_SHIELD })
    this.thrower = thrower
    this.direction = direction
    this.vector = DIRECTION_VECTORS[direction]
    this.phase = 'out'
    this.phaseSteps = 0
  }

  setPhase (phase) {
    this.phase = phase
    this.phaseSteps = 0
  }

  moveBy (distance) {
    this.x += this.vector[0] * distance
    this.y += this.vector[1] * distance
  }

  // Straight to the goriya: true once there
  homeIn () {
    const dx = this.thrower.x - this.x
    const dy = this.thrower.y - this.y
    const distance = Math.hypot(dx, dy)
    if (distance <= ENEMY_BOOMERANG_BACK) {
      return true
    }
    this.x += dx / distance * ENEMY_BOOMERANG_BACK
    this.y += dy / distance * ENEMY_BOOMERANG_BACK
    return false
  }

  process (map, link) {
    this.steps++
    this.phaseSteps++
    switch (this.phase) {
      case 'out':
        this.moveBy(ENEMY_BOOMERANG_FAST[this.steps % 2])
        if (this.phaseSteps >= ENEMY_BOOMERANG_FAST_STEPS) {
          this.setPhase('slow')
        }
        break
      case 'slow':
        this.moveBy(ENEMY_BOOMERANG_SLOW)
        if (this.phaseSteps >= ENEMY_BOOMERANG_SLOW_STEPS) {
          this.setPhase('slow_back')
        }
        break
      case 'slow_back':
        this.moveBy(-ENEMY_BOOMERANG_SLOW)
        if (this.phaseSteps >= ENEMY_BOOMERANG_SLOW_STEPS) {
          this.setPhase('back')
        }
        break
      case 'back':
        if (this.thrower.isDead || this.homeIn()) {
          this.done = true
          return
        }
    }
    if (this.phase !== 'back' && !isInside(map, this.x, this.y, this.width, this.height)) {
      this.setPhase('back')
    }
    if (this.phase === 'back' || !overlaps(this.getBox(), link.getBodyBox())) {
      return
    }
    this.setPhase('back')
    if (this.isBlockedBy(link)) {
      soundManager.play(resource.getSound(SOUND_SHIELD))
      return
    }
    link.hurt(this.damage, this.getBox())
  }

  draw (context) {
    drawImage(context, resource.getSprite('boomerang_wooden'), Math.floor(this.steps / ENEMY_BOOMERANG_FRAME_STEPS) % 4, this.x, this.y, this.width, this.height)
  }
}

export { Projectile, Rock, Arrow, Sword, Fireball, EnemyBoomerang }
