'use strict'

import soundManager from '../service/sound-manager'
import clock from '../service/clock'
import resource from '../resource'
import worldManager from '../service/world-manager'
import { ROOM, isInRoom } from './room-box'
import { TILE_WIDTH, TILE_HEIGHT, OPPOSITE_DIRECTIONS, DIRECTION_NORTH, DIRECTION_SOUTH, DIRECTION_WEST, DIRECTION_EAST, SOUND_DOOR_UNLOCK, SOUND_SECRET } from '../constant'

// The doors of the rooms of the dungeons, as in the ROM (bank 5, $917C; see docs/rom-analysis.md, Le passage des
// portes). A room (map.room) has the types of its four doors, its event and whether it has a block to push

// Types of the doors (tables 1 and 2 of the room): 2 and 3, the false walls, are walls in the first quest
export const DOOR_OPEN = 0
export const DOOR_BOMB = 4
export const DOOR_LOCKED = 5
export const DOOR_LOCKED_2 = 6
export const DOOR_SHUTTERS = 7

// Events of the rooms (6th table): what opens the shutters
export const EVENT_CLEARED = 1
export const EVENT_BLOCK = 4
export const EVENT_FIRST_ENEMY = 6
export const EVENT_CLEARED_ITEM = 7

const SIDES = [DIRECTION_NORTH, DIRECTION_SOUTH, DIRECTION_WEST, DIRECTION_EAST]
const VECTORS = { [DIRECTION_NORTH]: [0, -1], [DIRECTION_SOUTH]: [0, 1], [DIRECTION_WEST]: [-1, 0], [DIRECTION_EAST]: [1, 0] }

// Link stays in the room (see room-box.js) or in a doorway, on the axis of the door (x = $78, y = $8D)
const DOOR_X = 7.5 * TILE_WIDTH
const DOOR_Y = 5 * TILE_HEIGHT
// The hole of a wall to bomb, where a bomb opens it (the place of the passage of the door)
const HOLES = { [DIRECTION_NORTH]: [DOOR_X, TILE_HEIGHT], [DIRECTION_SOUTH]: [DOOR_X, 9 * TILE_HEIGHT], [DIRECTION_WEST]: [TILE_WIDTH, DOOR_Y], [DIRECTION_EAST]: [14 * TILE_WIDTH, DOOR_Y] }

// Measured in the ROM, in frames (game steps): Link waits 10 frames at a door he unlocks; the shutters close 10
// frames after he walked in; he pushes a block 17 frames before it moves
const UNLOCK_STEPS = 10
const SHUTTERS_STEPS = 10
const PUSH_STEPS = 17
// He walks in 16 NES pixels by an open or a locked door, 32 by any other (bank 5, $8831); he is carried 32 NES
// pixels out through a bombed wall (bank 5, $B077)
const SHORT_WALK = TILE_HEIGHT
const LONG_WALK = 2 * TILE_HEIGHT
const FRAME = 1000 / 60

const BLOCKING = '11111111'
const FREE = '00000000'
// The passage of the north and south doors: the right half of column 7, the left half of column 8
const RIGHT_FREE = '11000111'
const LEFT_FREE = '01111100'

const isLocked = type => type === DOOR_LOCKED || type === DOOR_LOCKED_2

// What the passage of a door shows: open, closed (lock), sealed (shutters), tunnel (bombed wall), or nothing
// (a wall)
function passage (map, side) {
  const type = map.room.doors[side]
  if (type === DOOR_OPEN) {
    return 'open'
  }
  if (isLocked(type)) {
    return map.openSides.has(side) ? 'open' : 'closed'
  }
  if (type === DOOR_SHUTTERS) {
    return map.shuttersOpen || map.heldOpen === side ? 'open' : 'sealed'
  }
  if (type === DOOR_BOMB && map.openSides.has(side)) {
    return 'tunnel'
  }
}

// Link may walk through: an open door, a door unlocked (once he has waited), open shutters
function canPass (map, side) {
  return passage(map, side) === 'open' && map.unlocking?.side !== side
}

function setTile (map, column, line, name, hitbox) {
  const tile = map.getTile(column, line)
  if (!tile) {
    return
  }
  tile.sprite = resource.getMapSprite(name, map.type) ?? tile.sprite
  tile.setHitbox(hitbox)
}

// The tiles of the doors as their state is (the data of the room has them shut)
export function applyDoors (map) {
  for (const side of SIDES) {
    const shown = passage(map, side)
    if (!shown) {
      continue
    }
    const open = shown === 'open'
    if (side === DIRECTION_NORTH || side === DIRECTION_SOUTH) {
      const [outer, inner] = side === DIRECTION_NORTH ? [0, 1] : [10, 9]
      if (shown === 'tunnel') {
        setTile(map, 7, inner, `dungeon_tunnel_${side}_0`, BLOCKING)
        setTile(map, 8, inner, `dungeon_tunnel_${side}_1`, BLOCKING)
        continue
      }
      setTile(map, 7, outer, `dungeon_door_${side}_top`, open ? RIGHT_FREE : BLOCKING)
      setTile(map, 8, outer, `dungeon_door_${side}_top`, open ? LEFT_FREE : BLOCKING)
      setTile(map, 7, inner, `dungeon_door_${side}_bottom_${shown}_0`, open ? RIGHT_FREE : BLOCKING)
      setTile(map, 8, inner, `dungeon_door_${side}_bottom_${shown}_1`, open ? LEFT_FREE : BLOCKING)
      continue
    }
    const [outer, inner] = side === DIRECTION_WEST ? [0, 1] : [15, 14]
    if (shown === 'tunnel') {
      setTile(map, inner, 5, `dungeon_tunnel_${side}`, BLOCKING)
      continue
    }
    setTile(map, outer, 5, `dungeon_door_${side}_top_1`, open ? FREE : BLOCKING)
    setTile(map, inner, 5, `dungeon_door_${side}_bottom_${shown}`, open ? FREE : BLOCKING)
  }
}

// The room next to this one, through that side
function neighbour (map, side) {
  const [dx, dy] = VECTORS[side]
  return worldManager.getMap(map.type, map.column + dx, map.line + dy)
}

// A door unlocked or a wall blown up stays open, on both sides (the flags of the rooms in the ROM, $06FF + room)
function openForGood (map, side) {
  map.openSides.add(side)
  neighbour(map, side)?.openSides.add(OPPOSITE_DIRECTIONS[side])
  applyDoors(map)
}

// Nothing left to fight: the enemies of the room are dead, the blade traps aside (before they come, those it has)
function isCleared (map) {
  return map.enemiesSpawned ? map.activeEnemies.every(enemy => enemy.isDead || !enemy.mustDie) : map.enemies.length === 0
}

// The event of the room is done: its shutters open
function isEventDone (map) {
  switch (map.room.event) {
    case EVENT_CLEARED:
    case EVENT_CLEARED_ITEM:
      return isCleared(map)
    case EVENT_FIRST_ENEMY:
      return map.enemiesSpawned ? !!map.activeEnemies[0]?.isDead || map.activeEnemies.length === 0 : map.enemies.length === 0
    case EVENT_BLOCK:
      return map.blockPushed
    default:
      return false
  }
}

const hasShutters = map => SIDES.some(side => map.room.doors[side] === DOOR_SHUTTERS)

// Before Link comes in (by the side arrival, if he comes through a door): its shutters are shut, but the one he
// comes through, until the event of the room is done; the block is back in its place
export function prepareRoom (map, arrival) {
  if (!map.room) {
    return
  }
  map.enemiesSpawned = false
  map.blockPushed = false
  map.pushSteps = 0
  map.pushedNow = false
  map.unlocking = undefined
  map.crossing = undefined
  map.shuttersOpen = isEventDone(map)
  map.heldOpen = !map.shuttersOpen && map.room.doors[arrival] === DOOR_SHUTTERS ? arrival : undefined
  map.closeSteps = 0
  applyDoors(map)
}

// Moves Link a distance his way, at his walking speed, without looking at the scenery
export function walkAlone (link, distance) {
  link.startWalking()
  return new Promise((resolve) => {
    let left = distance
    const timer = clock.repeat(() => {
      left -= link.walkAlone(left)
      if (left <= 0) {
        timer.cancel()
        link.stopWalking()
        resolve()
      }
    }, FRAME)
  })
}

// After the screen scrolled, Link walks into the room on his own: 16 NES pixels by an open or a locked door (he
// stays in the doorway), 32 by any other; then the shutters he came through close
export async function walkIn (map, link) {
  const type = map.room.doors[OPPOSITE_DIRECTIONS[link.direction]]
  await walkAlone(link, type === DOOR_OPEN || isLocked(type) ? SHORT_WALK : LONG_WALK)
  if (map.heldOpen) {
    map.closeSteps = SHUTTERS_STEPS
  }
}

// Through a bombed wall, Link is carried out to the edge of the screen
export function carryOut (link) {
  return walkAlone(link, LONG_WALK)
}

// One game step of the doors: the door being unlocked, the shutters closing behind Link, then opening when the
// event of the room is done; Link stops pushing the block
export function updateDoors (map) {
  if (!map.room) {
    return
  }
  if (map.unlocking && --map.unlocking.steps <= 0) {
    map.unlocking = undefined
  }
  if (map.closeSteps > 0 && --map.closeSteps === 0) {
    map.heldOpen = undefined
    applyDoors(map)
  }
  if (!map.shuttersOpen && hasShutters(map) && isEventDone(map)) {
    map.shuttersOpen = true
    map.heldOpen = undefined
    applyDoors(map)
    soundManager.play(resource.getSound(SOUND_DOOR_UNLOCK))
  }
  if (!map.pushedNow) {
    map.pushSteps = 0
  }
  map.pushedNow = false
}

// Link at (x, y), in a room: true if he is in a doorway he may go through (the scenery is not looked at), false
// if he is out of the room, undefined if the scenery decides (inside the room, or not in a dungeon)
export function roomAllows (map, x, y) {
  if (!map.room) {
    return undefined
  }
  if (isInRoom(map, x, y)) {
    return undefined
  }
  const rx = x - map.x
  const ry = y - map.y
  let side
  if (rx === DOOR_X) {
    side = ry < ROOM.top ? DIRECTION_NORTH : ry > ROOM.bottom ? DIRECTION_SOUTH : undefined
  } else if (ry === DOOR_Y) {
    side = rx < ROOM.left ? DIRECTION_WEST : rx > ROOM.right ? DIRECTION_EAST : undefined
  }
  return side !== undefined && canPass(map, side)
}

// Link stopped at the edge of the room, on the axis of a door, his way: a locked door opens with a key (or the
// magical key), and he walks through once it is open; through a bombed wall, he is carried
export function tryDoor (map, link) {
  if (!map.room) {
    return
  }
  const side = link.direction
  const rx = link.x - map.x
  const ry = link.y - map.y
  const at = {
    [DIRECTION_NORTH]: rx === DOOR_X && ry === ROOM.top,
    [DIRECTION_SOUTH]: rx === DOOR_X && ry === ROOM.bottom,
    [DIRECTION_WEST]: ry === DOOR_Y && rx === ROOM.left,
    [DIRECTION_EAST]: ry === DOOR_Y && rx === ROOM.right
  }[side]
  if (!at) {
    return
  }
  const type = map.room.doors[side]
  if (isLocked(type) && !map.openSides.has(side)) {
    if (!link.inventory.magicalKey) {
      if (link.inventory.keys <= 0) {
        return
      }
      link.inventory.keys--
    }
    map.unlocking = { side, steps: UNLOCK_STEPS }
    openForGood(map, side)
    soundManager.play(resource.getSound(SOUND_DOOR_UNLOCK))
    return
  }
  if (type === DOOR_BOMB && map.openSides.has(side)) {
    map.crossing = side
  }
}

// A bomb blowing up less than a tile from a wall to bomb opens it, on both sides. True if one opened
export function blowWalls (map, bomb) {
  if (!map.room) {
    return false
  }
  let blown = false
  for (const side of SIDES) {
    if (map.room.doors[side] !== DOOR_BOMB || map.openSides.has(side)) {
      continue
    }
    const [x, y] = HOLES[side]
    if (Math.abs(bomb.x - map.x - x) < TILE_WIDTH && Math.abs(bomb.y - map.y - y) < TILE_HEIGHT) {
      openForGood(map, side)
      blown = true
    }
  }
  if (blown) {
    soundManager.play(resource.getSound(SOUND_SECRET))
  }
  return blown
}

// The block to push: the first block of the middle line of the room, from the left (bank 5, $A808)
export function blockTile (map) {
  for (let column = 2; column <= 13; column++) {
    const tile = map.getTile(column, 5)
    if (tile?.original.sprite?.name?.startsWith('dungeon_block')) {
      return tile
    }
  }
}

// Link pushing the block of the room, once it is cleared (measured): after 17 frames, it slides one tile his
// way, any of the four, if the tile there is free. Once a visit
export function tryPushBlock (map, link) {
  if (!map.room?.block || map.blockPushed || map.pushes.length > 0 || !isCleared(map)) {
    return
  }
  const block = blockTile(map)
  const [dx, dy] = VECTORS[link.direction]
  const hitbox = link.getHitbox()
  const x = dx > 0 ? hitbox.x + hitbox.width : dx < 0 ? hitbox.x - 1 : hitbox.x
  const y = dy > 0 ? hitbox.y + hitbox.height : dy < 0 ? hitbox.y - 1 : hitbox.y
  if (!block || x < block.x || x >= block.x + block.width || y < block.y || y >= block.y + block.height || (dx !== 0 ? link.y !== block.y : link.x !== block.x)) {
    return
  }
  map.pushedNow = true
  map.pushSteps++
  if (map.pushSteps < PUSH_STEPS) {
    return
  }
  const target = map.getTile(block.column + dx, block.line + dy)
  if (!target || target.blockPoints.length > 0) {
    return
  }
  map.pushes.push(new BlockPush(map, block, target, dx, dy))
}

// The block sliding to the next tile, half an NES pixel a frame (measured): one display pixel a game step
class BlockPush {
  constructor (map, block, target, dx, dy) {
    this.map = map
    this.block = block
    this.target = target
    this.dx = dx
    this.dy = dy
    this.sprite = block.sprite
    this.offset = 0
    this.done = false
    // Both tiles block while it slides; the one it leaves shows the floor
    block.sprite = target.sprite
    target.setHitbox(block.hitbox)
  }

  process () {
    this.offset++
    if (this.offset < TILE_WIDTH) {
      return
    }
    this.target.sprite = this.sprite
    this.block.setHitbox(this.target.original.hitbox)
    this.map.blockPushed = true
    this.done = true
  }

  draw (context) {
    this.sprite.draw(context, this.block.x + this.dx * this.offset, this.block.y + this.dy * this.offset, this.block.width, this.block.height)
  }
}
