'use strict'

import { isBlocked, isBlockedByQuarters } from '../service/collision'
import { MAP_TYPE_CAVERNS, TILE_WIDTH, TILE_HEIGHT, TILES_PER_LINE, TILES_PER_COLUMN, DIRECTION_EAST, DIRECTION_NORTH, DIRECTION_SOUTH, DIRECTION_WEST, ENEMY_SPAWN_EDGE, ENEMY_PEAHAT, ENEMY_ZORA, ENEMY_BOULDER, ENEMY_GHINI, ENEMY_ARMOS, ENEMY_GEL, ENEMY_WALLMASTER, ENEMY_BLADE_TRAPS, NES_PIXEL } from '../constant'
import { STATE_SPAWNING, TERRAIN_INSET, inset, randomInt, shuffle } from './enemies/common'
import { Walker, Octorok, WALKERS, updateTarget } from './enemies/walker'
import { Tektite, TEKTITES } from './enemies/tektite'
import { Leever, LEEVERS, tickLeevers } from './enemies/leever'
import { Peahat } from './enemies/peahat'
import { Zora, findWater } from './enemies/zora'
import { Boulder } from './enemies/boulder'
import { Ghini } from './enemies/ghini'
import { Rock } from './enemies/projectile'
import { Keese, KEESES } from './enemies/keese'
import { Gel } from './enemies/gel'
import { Wallmaster, tickWallmasters } from './enemies/wallmaster'
import { BladeTrap, TRAP_CORNERS } from './enemies/blade-trap'

// How each kind of enemy comes on the screen: in a cloud on a free tile (walkers may also walk in
// from the edges), under the sand, in the water, or from above the screen
const IN_CLOUD = 'cloud'
const UNDER_SAND = 'sand'
const IN_WATER = 'water'
const FROM_ABOVE = 'above'
const IN_WALL = 'wall'
const IN_CORNERS = 'corners'
const KINDS = {
  ...Object.fromEntries(Object.keys(WALKERS).filter(type => type !== ENEMY_ARMOS && type !== ENEMY_GHINI).map(type => [type, { arrival: IN_CLOUD, create: (type, x, y, random) => Walker.inCloud(type, x, y, random), walks: true }])),
  ...Object.fromEntries(Object.keys(TEKTITES).map(type => [type, { arrival: IN_CLOUD, create: (type, x, y, random) => new Tektite(type, x, y, random) }])),
  ...Object.fromEntries(Object.keys(LEEVERS).map(type => [type, { arrival: UNDER_SAND, create: (type, x, y, random) => new Leever(type, x, y, random) }])),
  [ENEMY_PEAHAT]: { arrival: IN_CLOUD, create: (type, x, y, random) => new Peahat(type, x, y, random) },
  [ENEMY_GHINI]: { arrival: IN_CLOUD, create: (type, x, y, random) => Ghini.inCloud(type, x, y, random) },
  [ENEMY_ZORA]: { arrival: IN_WATER },
  [ENEMY_BOULDER]: { arrival: FROM_ABOVE },
  ...Object.fromEntries(Object.keys(KEESES).map(type => [type, { arrival: IN_CLOUD, create: (type, x, y, random) => new Keese(type, x, y, random) }])),
  [ENEMY_GEL]: { arrival: IN_CLOUD, create: (type, x, y, random) => new Gel(type, x, y, random) },
  // In the wall until Link goes along it
  [ENEMY_WALLMASTER]: { arrival: IN_WALL, create: (type, x, y, random) => new Wallmaster(type, x, y, random) },
  // In the corners of the room
  [ENEMY_BLADE_TRAPS]: { arrival: IN_CORNERS }
}
// The types the game moves
export const ENEMY_TYPES = Object.keys(KINDS)

// Steps between two enemies walking in from the edges
const MIN_ENTRY_DELAY = 10
const MAX_ENTRY_DELAY = 40
// No enemy appears that close to Link
const MIN_SPAWN_DISTANCE = 3 * TILE_WIDTH

// Places the screen is free at, far enough from Link (top-left corners of tiles)
function findFreeCells (map, link) {
  const cells = []
  for (let column = 0; column < TILES_PER_LINE; column++) {
    for (let line = 0; line < TILES_PER_COLUMN; line++) {
      const tile = map.getTile(column, line)
      const x = map.x + column * TILE_WIDTH
      const y = map.y + line * TILE_HEIGHT
      const isTransition = tile?.tileTransition && !tile.tileTransition.isEmpty()
      if (!isTransition && !isBlocked(map, inset(x, y, TILE_WIDTH, TILE_HEIGHT, TERRAIN_INSET)) && Math.hypot(x - link.x, y - link.y) >= MIN_SPAWN_DISTANCE) {
        cells.push({ column, line, x, y })
      }
    }
  }

  return cells
}

// Free tiles on the edges of the screen, with the place just outside them and the way in
function findEntries (cells) {
  const entries = []
  for (const cell of cells) {
    if (cell.column === 0) {
      entries.push({ x: cell.x - TILE_WIDTH, y: cell.y, direction: DIRECTION_EAST })
    }
    if (cell.column === TILES_PER_LINE - 1) {
      entries.push({ x: cell.x + TILE_WIDTH, y: cell.y, direction: DIRECTION_WEST })
    }
    if (cell.line === 0) {
      entries.push({ x: cell.x, y: cell.y - TILE_HEIGHT, direction: DIRECTION_SOUTH })
    }
    if (cell.line === TILES_PER_COLUMN - 1) {
      entries.push({ x: cell.x, y: cell.y + TILE_HEIGHT, direction: DIRECTION_NORTH })
    }
  }

  return entries
}

// Where the enemies of a room of a dungeon, or of a screen whose enemies come in a cloud, appear (bank 5, $8989):
// a list of 9 places for each way Link goes (table $8646 / $864A: right, left, down, up), a place in a byte
// (column in the low digit, line + 3 in the high one). A counter ($0524, 0 when the console starts) goes on from
// one room or screen to the next; a place is left out when the bottom left quarter of its tile blocks (the point
// x, y + 11), or when Link is less than $22 NES pixels from it both across and along ($8A04). The 9 places are
// taken in turn until there are 9 (the same one again if need be), one for each object
const ROOM_PLACES = {
  [DIRECTION_EAST]: [0x55, 0xb5, 0x78, 0x98, 0x7a, 0x9a, 0x6c, 0xac, 0x8d],
  [DIRECTION_WEST]: [0x82, 0x63, 0xa3, 0x75, 0x95, 0x77, 0x97, 0x5a, 0xba],
  [DIRECTION_SOUTH]: [0xa3, 0x75, 0xb5, 0x96, 0x87, 0x99, 0x7a, 0xba, 0xac],
  [DIRECTION_NORTH]: [0x63, 0x55, 0x95, 0x76, 0x88, 0x79, 0x5a, 0x9a, 0x6c]
}
const ROOM_SLOTS = 9
const NEAR_LINK = 0x22 * NES_PIXEL
let roomPlace = 0

// What the game remembers of the enemies killed, read in the ROM (bank 5, $92D7 leaving a room, $9293 coming in) and
// measured at level 1. Leaving a room by its doors or stairs, the enemies killed there are added to its count
// ($0560 + room); all of them killed, the room is cleared ($0F). Coming in, a room among the last 6 rooms or
// screens (the list $0621-$0626, filled in turn from $0620, bank 7 $EADD) has its enemies less those killed (none
// when cleared); another room has them all when it was cleared, its enemies less those killed otherwise. The list is
// emptied going in or out of a level and when the level starts again ($03); the counts are forgotten out of it
const RECENT_ROOMS = 6
const CLEARED = 0x0f
const recent = { rooms: Array(RECENT_ROOMS).fill(0), next: 0 }

// A new game: the counter of the places and the list of the last rooms start again
export function resetRoomPlaces () {
  roomPlace = 0
  recent.rooms.fill(0)
  recent.next = 0
}

// Going in or out of a level, the level starting again
export function forgetRecentRooms () {
  recent.rooms.fill(0)
}

// Out of a level: the counts of its rooms
export function forgetKills (maps) {
  for (const map of maps) {
    map.killed = 0
  }
}

const roomNumber = map => map.column + 16 * map.line

// A room or a screen goes in the list of the last ones, if it is not there yet
function visit (map) {
  const number = roomNumber(map)
  if (!recent.rooms.includes(number)) {
    recent.rooms[recent.next] = number
    recent.next = (recent.next + 1) % RECENT_ROOMS
  }
}

// Leaving a room of a dungeon by its doors or its stairs: the enemies killed there
export function leaveRoom (map) {
  if (!map.room || !map.enemiesSpawned) {
    return
  }
  const killed = map.killedNow + map.activeEnemies.filter(enemy => enemy.isDead).length
  if (killed < map.enemyCount) {
    map.killed += killed
  } else {
    map.killed = CLEARED
  }
}

// The enemies of the room this time: the first ones of its list, less those killed
function enemiesLeft (map, types) {
  if (!recent.rooms.includes(roomNumber(map)) && map.killed === CLEARED) {
    map.killed = 0
  }
  return types.slice(0, map.killed === CLEARED ? 0 : Math.max(0, types.length - map.killed))
}

function findRoomPlaces (map, link) {
  const list = ROOM_PLACES[link.direction] ?? ROOM_PLACES[DIRECTION_NORTH]
  const places = []
  for (let tries = 0; places.length < ROOM_SLOTS && tries < 10 * ROOM_SLOTS; tries++) {
    const place = list[roomPlace]
    roomPlace = (roomPlace + 1) % list.length
    const column = place & 0x0f
    const line = (place >> 4) - 3
    const x = map.x + column * TILE_WIDTH
    const y = map.y + line * TILE_HEIGHT
    const quarter = { x, y: y + TILE_HEIGHT / 2, width: TILE_WIDTH / 2, height: TILE_HEIGHT / 2 }
    const blocked = !map.getTile(column, line) || isBlockedByQuarters(map, quarter)
    const near = Math.abs(link.x - x) < NEAR_LINK && Math.abs(link.y - y) < NEAR_LINK
    if (!blocked && !near) {
      places.push({ x, y })
    }
  }
  return places
}

// The enemies of a room of a dungeon, in the order of their places (1, 2…): in a cloud at the places of the
// room, the blade traps in the corners, the wallmasters in the walls
function spawnRoomEnemies (map, link, types, random) {
  const places = findRoomPlaces(map, link)
  const enemies = []
  types.forEach((type, i) => {
    const kind = KINDS[type]
    const place = places[i % places.length] ?? { x: map.x, y: map.y }
    let enemy
    if (kind.arrival === IN_CORNERS) {
      const corner = TRAP_CORNERS[i % TRAP_CORNERS.length]
      enemy = new BladeTrap(type, map.x + corner.column * TILE_WIDTH, map.y + corner.line * TILE_HEIGHT, corner.ways, random)
      enemy.setState(STATE_SPAWNING)
    } else {
      enemy = kind.create(type, place.x, place.y, random)
      if (kind.arrival === IN_CLOUD && !kind.walks) {
        enemy.setState(STATE_SPAWNING)
      }
    }
    enemy.slot = i + 1
    enemies.push(enemy)
  })
  return enemies
}

// The enemies of a screen or a room, when Link arrives on it; it goes in the list of the last ones (not a cave)
export function spawnEnemies (map, link, random = Math.random) {
  const enemies = createEnemies(map, link, random)
  if (map.type !== MAP_TYPE_CAVERNS) {
    visit(map)
  }
  return enemies
}

// Walkers of a screen whose enemies come from the edges walk in (in a cloud on a screen with no free edge); the
// others arrive their own way, those in a cloud at the places of the lists. In a dungeon, see spawnRoomEnemies
function createEnemies (map, link, random) {
  let types = map.enemies.flatMap(({ type, count }) => KINDS[type] ? Array(count).fill(type) : [])
  if (map.room) {
    types = enemiesLeft(map, types)
    map.enemyCount = types.length
    map.killedNow = 0
  }
  if (types.length === 0) {
    return []
  }
  if (map.room) {
    return spawnRoomEnemies(map, link, types, random)
  }
  const fromEdges = map.enemySpawn === ENEMY_SPAWN_EDGE
  const places = fromEdges ? [] : findRoomPlaces(map, link)
  const cells = shuffle(random, findFreeCells(map, link))
  const entries = fromEdges ? shuffle(random, findEntries(cells)) : []
  const water = findWater(map)

  const enemies = []
  let delay = 0
  types.forEach((type, i) => {
    const kind = KINDS[type]
    if (kind.walks && entries.length > 0) {
      const entry = entries[i % entries.length]
      delay += randomInt(random, MIN_ENTRY_DELAY, MAX_ENTRY_DELAY)
      enemies.push(Walker.fromEdge(type, entry.x, entry.y, entry.direction, delay, random))
      return
    }
    switch (kind.arrival) {
      case IN_WATER:
        if (water.length > 0) {
          enemies.push(new Zora(type, water, random))
        }
        return
      case FROM_ABOVE:
        enemies.push(new Boulder(type, map, random))
        return
    }
    const cell = places.length > 0 ? places[i % places.length] : cells[i % cells.length]
    if (!cell) {
      return
    }
    const enemy = kind.create(type, cell.x, cell.y, random)
    if (kind.arrival === IN_CLOUD && !kind.walks) {
      enemy.setState(STATE_SPAWNING)
    }
    enemies.push(enemy)
  })

  return enemies
}

// One game step for the enemies of the screen, their projectiles, what they left, Link's bomb, flames, flying
// sword, boomerang, arrow, magic and bait, and the rock he pushes
export function updateEnemies (map, link) {
  updateTarget(map, link)
  tickLeevers(map)
  tickWallmasters(map)
  for (const bomb of map.bombs) {
    bomb.process(map, link)
  }
  for (const flame of map.flames) {
    flame.process(map, link)
  }
  for (const push of map.pushes) {
    push.process()
  }
  for (const beam of map.beams) {
    beam.process(map, link)
  }
  // Before the enemies: the bait becomes their target
  for (const weapon of map.weapons) {
    weapon.process(map, link)
  }
  for (const effect of map.whistles) {
    effect.process(map, link)
  }
  for (const enemy of map.activeEnemies) {
    enemy.process(map, link)
  }
  for (const projectile of map.projectiles) {
    projectile.process(map, link)
  }
  for (const drop of map.drops) {
    drop.process(map, link)
  }
  // The enemies killed in the room this time (see leaveRoom)
  map.killedNow = (map.killedNow ?? 0) + map.activeEnemies.filter(enemy => enemy.isDead).length
  map.activeEnemies = map.activeEnemies.filter(enemy => !enemy.isDead)
  map.projectiles = map.projectiles.filter(projectile => !projectile.done)
  map.drops = map.drops.filter(drop => !drop.done)
  map.bombs = map.bombs.filter(bomb => !bomb.done)
  map.flames = map.flames.filter(flame => !flame.done)
  map.pushes = map.pushes.filter(push => !push.done)
  map.beams = map.beams.filter(beam => !beam.done)
  map.weapons = map.weapons.filter(weapon => !weapon.done)
  map.whistles = map.whistles.filter(effect => !effect.done)
}

export { Octorok, Rock }
