'use strict'

import { ENEMY_SPAWN_CLOUD, TILE_WIDTH, TILE_HEIGHT, SPRITE_TEXT_COLOR_WHITE } from '../constant'
import { spawnEnemies } from './enemy'
import { getPriceLabel } from './cave'
import { restoreSecrets } from './secret'
import { drawLadder } from './water'
import resource from '../resource'
import textManager from '../service/text-manager'

class Map {
  constructor (column, line, x, y, width, height, type, tiles, characters, items, extras, enemies = [], enemySpawn = ENEMY_SPAWN_CLOUD, cave = undefined, room = undefined) {
    this.column = column
    this.line = line
    this.x = x
    this.y = y
    this.offsetX = 0
    this.offsetY = 0
    this.width = width
    this.height = height
    this.type = type
    this.tiles = tiles
    this.characters = characters
    this.items = items
    this.extras = extras
    // What the screen holds ([{ type, count }]) and how they arrive; the enemies there are only
    // while Link is on the screen
    this.enemies = enemies
    this.enemySpawn = enemySpawn
    // What the cave does (CAVE_* in constant.js), undefined for an ordinary screen
    this.cave = cave
    // A room of a dungeon: the types of its doors, its event and whether it has a block to push ({ doors: { north,
    // south, west, east }, event, block }, see dungeon.js), and the sides opened for good (keys, bombs)
    this.room = room
    this.openSides = new Set()
    // The enemies came since Link arrived (the room is cleared when they are all dead); in a room, how many came,
    // how many were killed this time, and those killed before it is cleared (see leaveRoom)
    this.enemiesSpawned = false
    this.enemyCount = 0
    this.killedNow = 0
    this.killed = 0
    // A cave whose gift was taken is empty from the next visit on
    this.emptied = false
    // Nothing shown yet (potion shop before the letter); set by the game
    this.closed = false
    this.activeEnemies = []
    this.projectiles = []
    // What the dead enemies left, and whether a clock stopped the enemies
    this.drops = []
    this.frozen = false
    // The bomb Link put down, his flames, the rock he pushes, and whether the blue candle burnt here
    this.bombs = []
    this.flames = []
    this.pushes = []
    this.candleUsed = false
    // The flying sword
    this.beams = []
    // Link's boomerang, arrow, magic of the wand and bait (see weapons.js)
    this.weapons = []
    // The ladder over the water (see water.js)
    this.ladder = undefined
    // What the whistle does: a whirlwind, the lake drained
    this.whistles = []

    this.savedItems = []
    this.savedCharacters = []
    this.mapPath = this.getMapPath()
  }

  get character () {
    return this.characters[0]
  }

  getMapPath () {
    const path = new Path2D()
    path.rect(this.x, this.y, this.width, this.height)

    return path
  }

  init () {
    if (this.emptied) {
      this.characters = []
      this.items = []
    }
    for (const character of this.characters) {
      character.init()
    }
    for (const item of this.items) {
      item.init()
      item.label = getPriceLabel(this.cave, item.price)
    }
    for (const extra of this.extras) {
      extra.init()
    }
  }

  reset () {
    for (const character of this.characters) {
      character.reset()
    }
    for (const item of this.items) {
      item.reset()
    }
    for (const extra of this.extras) {
      extra.reset()
    }
    this.clearEnemies()
    restoreSecrets(this)
  }

  spawnEnemies (link, random) {
    this.clearEnemies()
    this.activeEnemies = spawnEnemies(this, link, random)
    this.enemiesSpawned = true
  }

  clearEnemies () {
    this.activeEnemies = []
    this.projectiles = []
    this.drops = []
    this.frozen = false
    this.bombs = []
    this.flames = []
    this.pushes = []
    this.candleUsed = false
    this.beams = []
    this.weapons = []
    this.whistles = []
    this.ladder = undefined
    // What the walkers go after (see updateTarget)
    this.target = undefined
    this.targetFrames = 0
    this.targetMirrored = true
    // Before a red leever comes out (see tickLeevers)
    this.leeverCooldown = undefined
    // Before the next wallmaster, and the one holding Link (see wallmaster.js)
    this.wallmasterSteps = 0
    this.wallmasterHolding = false
    this.carriedOff = false
  }

  // recolour: the tiles in other colours (image → image), while Link dies
  draw (context, recolour) {
    context.save()
    context.translate(this.offsetX, this.offsetY)

    for (const tile of this.tilesIterator()) {
      tile.draw(context, undefined, undefined, recolour)
    }
    for (const push of this.pushes) {
      push.draw(context)
    }
    drawLadder(context, this)

    for (const character of this.characters) {
      character.draw(context)
    }

    if (!this.closed) {
      for (const item of this.items) {
        item.draw(context)
      }
      this.drawPriceRow(context)
    }

    for (const extra of this.extras) {
      extra.draw(context)
    }

    // Enemies walking in from outside only show once on the screen
    context.save()
    context.clip(this.mapPath)
    for (const drop of this.drops) {
      drop.draw(context)
    }
    for (const bomb of this.bombs) {
      bomb.draw(context)
    }
    for (const flame of this.flames) {
      flame.draw(context)
    }
    for (const beam of this.beams) {
      beam.draw(context)
    }
    for (const weapon of this.weapons) {
      weapon.draw(context)
    }
    for (const effect of this.whistles) {
      effect.draw(context)
    }
    for (const enemy of this.activeEnemies) {
      enemy.draw(context)
    }
    for (const projectile of this.projectiles) {
      projectile.draw(context)
    }
    context.restore()

    context.translate(-this.offsetX, -this.offsetY)
    context.restore()
  }

  // A rupee and "x" in front of the prices, as in the shops of the original
  drawPriceRow (context) {
    if (!this.items.some(item => item.enabled && item.price && item.label)) {
      return
    }
    const y = this.y + 7 * TILE_HEIGHT
    resource.getSprite('item_rupee')?.draw(context, this.x + 2.75 * TILE_WIDTH, y - TILE_HEIGHT / 4, TILE_WIDTH, TILE_HEIGHT)
    textManager.drawLine(context, 'x', SPRITE_TEXT_COLOR_WHITE, this.x + 4 * TILE_WIDTH, y)
  }

  drawBlockingZones (context, color) {
    context.save()
    context.translate(this.offsetX, this.offsetY)
    context.globalAlpha = 0.5
    context.fillStyle = color
    for (const tile of this.tilesIterator()) {
      context.fill(tile.blockPath)
    }
    context.translate(-this.offsetX, -this.offsetY)
    context.restore()
  }

  * tilesIterator () {
    for (let column = 0; column < this.tiles.length; column++) {
      for (let line = 0; line < this.tiles[column].length; line++) {
        yield this.tiles[column][line]
      }
    }
  }

  getTile (column, line) {
    return this.tiles[column] ? this.tiles[column][line] : undefined
  }
}

export { Map }
